package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import org.springframework.context.annotation.Lazy;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Durable warehouse census, bounded keyset discovery and single-SKU batch snapshots. No stock writes. */
@Service public class WarehouseFullReconciliation {
 @Resource WmsStore db; @Resource WarehouseControlScope scope; @Resource StockMovementClient stock;
 @Resource WarehouseReconciliationGate gate; @Resource @Lazy WarehouseReconciliation reconciliation; @Resource @Lazy WarehouseControlWork work;
 private long n(Map<String,Object>d,String k){return scope.n(d,k);}
 private Map<String,Object> get(String c,long id){Map<String,Object>d=db.one("SELECT * FROM warehouse_reconciliation WHERE company_code=? AND id=?",c,id);require("FULL".equals(d.get("scope_mode")),"请选择全仓检查任务");return d;}
 @SuppressWarnings("unchecked") private List<String> strings(Object o){return (List<String>)o;}
 public Map<String,Object> preview(String c,String store){Map<String,Object>w=scope.warehouse(c,store);scope.route(c,w);return map("owner_code",w.get("actual_owner"),"real_store",w.get("real_store_code"),"stores",scope.stores(c,w),"native_full_wms",false);}
 public List<Map<String,Object>> search(String c,String store,String keyword){Map<String,Object>w=scope.warehouse(c,store);List<String>stores=scope.stores(c,w);Map<String,Object>r=scope.reply(stock.execute(c,"checkSearch",map("stores",stores,"keyword",keyword)));List<Map<String,Object>>rows=scope.rows(r.get("rows"));List<String>skus=new ArrayList<>();for(Map<String,Object>x:rows)skus.add(text(x.get("sku_sn")));if(!skus.isEmpty()){Map<String,Map<String,Object>>goods=scope.checkGoods(c,skus);for(Map<String,Object>x:rows)x.put("goods_name",goods.getOrDefault(text(x.get("sku_sn")),Collections.emptyMap()).get("goods_name"));}return rows;}
 public long create(String c,Map<String,Object>cmd,String actor){
  String key=required(cmd,"request_key",64),store=required(cmd,"store_code",64),digest=scope.hash(cmd);
  Map<String,Object>w=scope.warehouse(c,store),route=scope.route(c,w);List<String>stores=scope.stores(c,w),warehouse=new ArrayList<>();
  if(cmd.get("warehouse_skus")!=null){require(cmd.get("warehouse_skus") instanceof List,"仓库清单格式无效");List<?> input=(List<?>)cmd.get("warehouse_skus");require(!input.isEmpty()&&input.size()<=20000,"仓库完整清单须为1至20000个SKU；超过上限请联系管理员分区检查");TreeSet<String>unique=new TreeSet<>();for(Object v:input){String s=text(v);require(!s.isEmpty()&&s.length()<=128,"仓库清单SKU为空或过长");unique.add(s);}warehouse.addAll(unique);require(Boolean.TRUE.equals(cmd.get("warehouse_list_confirmed")),"请确认清单属于本货主实仓且包含零库存商品");required(cmd,"warehouse_list_evidence",500);}
  Map<String,Object>range=map("stores",stores,"skus",Collections.emptyList(),"batch_code","","warehouse_skus",warehouse,"warehouse_list_evidence",text(cmd.get("warehouse_list_evidence")));
  return db.tx().execute(tx->{List<Map<String,Object>>old=db.jdbc.queryForList("SELECT id,request_hash FROM warehouse_reconciliation WHERE company_code=? AND request_key=?",c,key);if(!old.isEmpty()){require(digest.equals(old.get(0).get("request_hash")),"相同请求内容已变化");return n(old.get(0),"id");}long id=db.insert("warehouse_reconciliation",map("company_code",c,"document_sn","DZ"+UUID.randomUUID().toString().replace("-",""),"request_key",key,"request_hash",digest,"store_code",store,"owner_code",w.get("actual_owner"),"real_store",w.get("real_store_code"),"method","stock.query","connection_id",route.get("connection_id"),"scope_json",db.encode(range),"scope_hash",scope.hash(range),"route_json",db.encode(route),"scope_mode","FULL","coverage",warehouse.isEmpty()?"OMS_LIST":"OMS_WMS_LIST","progress_json",db.encode(map("stage","INVENTORY","cursor",0,"started",false,"generated",false,"started_at",java.time.LocalDateTime.now().toString())),"created_by",actor));scope.audit(c,"RECONCILIATION",id,"CREATE",actor,"全仓只读检查；覆盖"+(warehouse.isEmpty()?"OMS库存与在途单据商品清单":"OMS及人工确认的仓库完整商品清单"));work.ready(c,id,false);return id;});
 }
 /** Also discover pending-document-only SKUs that have not acquired an inventory record yet. */
 private List<Map<String,Object>> pendingSkus(String c,List<String>stores,String after){String sm=String.join(",",Collections.nCopies(stores.size(),"?"));List<Object>a=new ArrayList<>();List<String>sql=new ArrayList<>();
  sql.add("SELECT g.sku_sn FROM wms_tickets t JOIN wms_tickets_goods g ON g.company_code=t.company_key AND g.sn=t.sn WHERE t.company_key=? AND t.wms_simulation_code IN("+sm+") AND t.actual_warehouse=1 AND t.inventory_status<>2");a.add(c);a.addAll(stores);
  sql.add("SELECT l.sku_sn FROM purchase_return r JOIN purchase_return_line l ON l.company_code=r.company_code AND l.return_id=r.id WHERE r.company_code=? AND r.store_code IN("+sm+") AND r.state NOT IN('DRAFT','COMPLETED','CANCELED')");a.add(c);a.addAll(stores);
  sql.add("SELECT l.sku_sn FROM warehouse_transfer d JOIN warehouse_transfer_line l ON l.company_code=d.company_code AND l.transfer_id=d.id WHERE d.company_code=? AND (d.source_store IN("+sm+") OR d.target_store IN("+sm+")) AND d.state NOT IN('DRAFT','COMPLETED')");a.add(c);a.addAll(stores);a.addAll(stores);
  sql.add("SELECT l.sku_sn FROM purchase_return_reclaim h JOIN purchase_return_reclaim_line x ON x.company_code=h.company_code AND x.reclaim_id=h.id JOIN purchase_return_line l ON l.company_code=x.company_code AND l.id=x.return_line_id WHERE h.company_code=? AND h.store_code IN("+sm+") AND h.state IN('ACTIVE','CANCELING')");a.add(c);a.addAll(stores);
  sql.add("SELECT p.sku_sn FROM wms_process_order p WHERE p.company_code=? AND p.store_code IN("+sm+") AND p.state NOT IN('DRAFT','COMPLETED','STOPPED')");a.add(c);a.addAll(stores);
  a.add(after);return db.jdbc.queryForList("SELECT DISTINCT sku_sn COLLATE utf8mb4_bin sku_sn FROM ("+String.join(" UNION ALL ",sql)+") candidates WHERE sku_sn COLLATE utf8mb4_bin>? AND sku_sn<>'' ORDER BY sku_sn COLLATE utf8mb4_bin LIMIT 100",a.toArray());
 }
 private void add(String c,Map<String,Object>d,Map<String,Object>range,List<String>skus){List<Object[]>batch=new ArrayList<>();for(String sku:new TreeSet<>(skus)){Map<String,Object>r=map("stores",range.get("stores"),"skus",Collections.singletonList(sku),"batch_code","");batch.add(new Object[]{c,"DZ"+UUID.randomUUID().toString().replace("-",""),"FULL_"+d.get("id")+"_"+scope.hash(sku).substring(0,32),scope.hash(r),d.get("store_code"),d.get("owner_code"),d.get("real_store"),d.get("connection_id"),db.encode(r),scope.hash(r),d.get("route_json"),d.get("created_by"),d.get("id"),sku});}if(!batch.isEmpty())db.tx().execute(tx->{int[] changes=db.jdbc.batchUpdate("INSERT IGNORE INTO warehouse_reconciliation(company_code,document_sn,request_key,request_hash,store_code,owner_code,real_store,method,connection_id,scope_json,scope_hash,route_json,created_by,scope_mode,parent_id,item_sku) VALUES(?,?,?,?,?,?,?,'stock.query',?,?,?,?,?,'ITEM',?,?)",batch);long added=0;boolean unknown=false;for(int value:changes){if(value<0)unknown=true;else added+=value;}if(unknown){long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation WHERE company_code=? AND parent_id=?",Long.class,c,d.get("id"));db.jdbc.update("UPDATE warehouse_reconciliation SET discovered_count=? WHERE company_code=? AND id=?",total,c,d.get("id"));}else db.jdbc.update("UPDATE warehouse_reconciliation SET discovered_count=discovered_count+? WHERE company_code=? AND id=?",added,c,d.get("id"));return null;});}
 private void generate(String c,Map<String,Object>d,Map<String,Object>range,Map<String,Object>p){String stage=text(p.get("stage"));List<String>skus=new ArrayList<>();
  if(stage.equals("INVENTORY")){Map<String,Object>r=scope.reply(stock.execute(c,"discover",map("stores",range.get("stores"),"cursor",n(p,"cursor"),"maximum",n(p,"maximum"),"started",Boolean.TRUE.equals(p.get("started")))));for(Map<String,Object>x:scope.rows(r.get("rows")))skus.add(required(x,"sku_sn",128));p.put("cursor",r.get("cursor"));p.put("maximum",r.get("maximum"));p.put("started",true);if(Boolean.TRUE.equals(r.get("done")))p.put("stage","DOCUMENTS");}
  else if(stage.equals("DOCUMENTS")){List<Map<String,Object>>rows=pendingSkus(c,strings(range.get("stores")),text(p.get("document_cursor")));for(Map<String,Object>x:rows)skus.add(text(x.get("sku_sn")));if(!rows.isEmpty())p.put("document_cursor",skus.get(skus.size()-1));if(rows.size()<100)p.put("stage","PROCESSES");}
  else if(stage.equals("PROCESSES")){List<String>stores=strings(range.get("stores"));List<Object>a=new ArrayList<>();a.add(c);a.addAll(stores);a.add(n(p,"process_cursor"));List<Map<String,Object>>tasks=db.jdbc.queryForList("SELECT id,sku_sn,recipe_json FROM wms_process_order WHERE company_code=? AND store_code IN("+String.join(",",Collections.nCopies(stores.size(),"?"))+") AND state NOT IN('DRAFT','COMPLETED','STOPPED') AND id>? ORDER BY id LIMIT 1",a.toArray());if(tasks.isEmpty())p.put("stage","WAREHOUSE_LIST");else{Map<String,Object>task=tasks.get(0),recipe=scope.obj(task.get("recipe_json"));skus.add(required(task,"sku_sn",128));List<Map<String,Object>>components=scope.rows(recipe.get("components"));require(components.size()<=500,"加工组件超过500种，请先核查加工单");for(Map<String,Object>component:components)skus.add(required(component,"sku_sn",128));p.put("process_cursor",task.get("id"));}}
  else if(stage.equals("WAREHOUSE_LIST")){List<String>list=strings(range.get("warehouse_skus"));int start=Math.toIntExact(n(p,"warehouse_cursor")),end=Math.min(start+100,list.size());skus.addAll(list.subList(start,end));p.put("warehouse_cursor",end);if(end==list.size()){p.put("stage","QUERY");p.put("generated",true);}}
  add(c,d,range,skus);
 }
 private void project(String c,long parent,Map<String,Object>child){long childId=n(child,"id");db.tx().execute(tx->{Map<String,Object>locked=db.one("SELECT result_saved FROM warehouse_reconciliation WHERE company_code=? AND id=? FOR UPDATE",c,childId);if(n(locked,"result_saved")==1)return null;
   List<Map<String,Object>>rows;List<Map<String,Object>>pending=Collections.emptyList();if("COMPLETED".equals(child.get("state"))){Map<String,Object>result=scope.obj(child.get("result_json"));rows=scope.rows(result.get("rows"));pending=scope.rows(result.get("pending_documents"));}else rows=Collections.singletonList(map("sku_sn",child.get("item_sku"),"status","QUERY_FAILED","wms_physical",null,"difference",null,"sources",Collections.emptyList(),"error",child.get("last_error")));
   List<Object[]>args=new ArrayList<>();for(Map<String,Object>r:rows){r.put("child_id",childId);r.put("pending_documents",pending);args.add(new Object[]{c,parent,childId,scope.hash(r),r.get("sku_sn"),r.get("status"),r.get("difference"),db.encode(r)});}if(!args.isEmpty())db.jdbc.batchUpdate("INSERT IGNORE INTO warehouse_reconciliation_result(company_code,parent_id,child_id,row_hash,sku_sn,status,difference,row_json) VALUES(?,?,?,?,?,?,?,?)",args);db.jdbc.update("UPDATE warehouse_reconciliation SET result_saved=1,result_rows=? WHERE company_code=? AND id=?",rows.size(),c,childId);db.jdbc.update("UPDATE warehouse_reconciliation SET successful_count=successful_count+?,failed_count=failed_count+?,result_count=result_count+?,difference_count=difference_count+?,attention_count=attention_count+? WHERE company_code=? AND id=?","COMPLETED".equals(child.get("state"))?1:0,"FAILED".equals(child.get("state"))?1:0,rows.size(),n(child,"difference_count"),n(child,"attention_count"),c,parent);return null;});}
 public void process(String c,long id){Map<String,Object>d=get(c,id);if(!Arrays.asList("PENDING","RUNNING","STOPPING").contains(d.get("state")))return;String token=UUID.randomUUID().toString();if(!gate.acquire(c,d,token)){db.jdbc.update("UPDATE warehouse_reconciliation SET next_attempt_at=DATE_ADD(NOW(),INTERVAL 10 SECOND) WHERE company_code=? AND id=?",c,id);return;}
  boolean again=false;try{if(db.jdbc.update("UPDATE warehouse_reconciliation SET state=IF(stop_requested=1,'STOPPING','RUNNING'),lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",token,c,id)==0)return;
   Map<String,Object>p=scope.obj(d.get("progress_json")),range=scope.obj(d.get("scope_json"));p.remove("finished_at");if(db.jdbc.queryForObject("SELECT stop_requested FROM warehouse_reconciliation WHERE company_code=? AND id=?",Integer.class,c,id)==0){if(!Boolean.TRUE.equals(p.get("generated")))generate(c,d,range,p);
    List<Map<String,Object>>items=db.jdbc.queryForList("SELECT id FROM warehouse_reconciliation WHERE company_code=? AND parent_id=? AND (state='PENDING' OR (state='RUNNING' AND (lease_until IS NULL OR lease_until<NOW()))) ORDER BY id LIMIT 5",c,id);for(Map<String,Object>x:items){if(db.jdbc.queryForObject("SELECT stop_requested FROM warehouse_reconciliation WHERE company_code=? AND id=?",Integer.class,c,id)==1)break;gate.renew(c,d,token);reconciliation.processItem(c,n(x,"id"),()->{gate.renew(c,d,token);require(db.jdbc.update("UPDATE warehouse_reconciliation SET lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=? AND lease_token=?",c,id,token)==1,"全仓任务租约已变化");});}}
   for(Map<String,Object>child:db.jdbc.queryForList("SELECT * FROM warehouse_reconciliation WHERE company_code=? AND parent_id=? AND state IN('COMPLETED','FAILED') AND result_saved=0 ORDER BY id LIMIT 5",c,id))project(c,id,child);
   Map<String,Object>head=get(c,id);Map<String,Object>counts=map("total",n(head,"discovered_count"),"successful",n(head,"successful_count"),"failed",n(head,"failed_count"),"remaining",n(head,"discovered_count")-n(head,"successful_count")-n(head,"failed_count"),"result_rows",n(head,"result_count"),"differences",n(head,"difference_count"),"attention",n(head,"attention_count"));p.putAll(counts);boolean stop=db.jdbc.queryForObject("SELECT stop_requested FROM warehouse_reconciliation WHERE company_code=? AND id=?",Integer.class,c,id)==1,done=Boolean.TRUE.equals(p.get("generated"))&&n(counts,"remaining")==0;String state=stop?"STOPPED":done?(n(counts,"failed")>0?"PARTIAL":"COMPLETED"):"RUNNING";if(stop||done)p.put("finished_at",java.time.LocalDateTime.now().toString());db.jdbc.update("UPDATE warehouse_reconciliation SET state=?,progress_json=?,difference_count=?,attention_count=?,last_error='',lease_until=NULL,lease_token=NULL,next_attempt_at=NOW() WHERE company_code=? AND id=? AND lease_token=?",state,db.encode(p),n(counts,"differences"),n(counts,"attention"),c,id,token);again=state.equals("RUNNING");
  }catch(Exception e){db.jdbc.update("UPDATE warehouse_reconciliation SET state='FAILED',last_error=?,lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",scope.safe(e),c,id,token);}finally{gate.release(c,d,token);}if(again)work.ready(c,id,false);
 }
 public Map<String,Object> control(String c,long id,String action,String actor){get(c,id);db.tx().execute(tx->{Map<String,Object>d=db.one("SELECT * FROM warehouse_reconciliation WHERE company_code=? AND id=? FOR UPDATE",c,id);String state=text(d.get("state"));if(action.equals("stop")){require(Arrays.asList("PENDING","RUNNING","STOPPING").contains(state),"该任务不在执行中");db.jdbc.update("UPDATE warehouse_reconciliation SET stop_requested=1,state='STOPPING' WHERE company_code=? AND id=?",c,id);}else{require(Arrays.asList("STOPPED","PARTIAL","FAILED").contains(state),"请等待当前任务结束或停止");require(d.get("lease_until")==null,"当前商品尚未完成，请稍后再试");if(action.equals("retryFailed")){require(!state.equals("STOPPED"),"已停止任务请先继续未查商品，再重试失败部分");long failedRows=db.jdbc.queryForObject("SELECT COALESCE(SUM(result_rows),0) FROM warehouse_reconciliation WHERE company_code=? AND parent_id=? AND state='FAILED'",Long.class,c,id);db.jdbc.update("UPDATE warehouse_reconciliation SET failed_count=0,result_count=result_count-? WHERE company_code=? AND id=?",failedRows,c,id);db.jdbc.update("DELETE r FROM warehouse_reconciliation_result r JOIN warehouse_reconciliation x ON x.company_code=r.company_code AND x.id=r.child_id WHERE r.company_code=? AND r.parent_id=? AND x.state='FAILED'",c,id);db.jdbc.update("UPDATE warehouse_reconciliation SET state='PENDING',result_saved=0,result_rows=0,last_error='',next_attempt_at=NOW() WHERE company_code=? AND parent_id=? AND state='FAILED'",c,id);}else require(action.equals("resume"),"不支持此操作");db.jdbc.update("UPDATE warehouse_reconciliation SET stop_requested=0,state='PENDING',next_attempt_at=NOW(),last_error='' WHERE company_code=? AND id=?",c,id);}scope.audit(c,"RECONCILIATION",id,action,actor,"沿用原范围；已成功商品保留快照");work.ready(c,id,false);return null;});return reconciliation.detail(c,id);}
 public Map<String,Object> results(String c,long id,Map<String,String>q){get(c,id);String status=text(q.get("status")),sku=text(q.get("sku_sn"));require(status.matches("[A-Z_]{0,40}")&&sku.length()<=128,"结果筛选无效");int page=q.containsKey("pageNum")?Integer.parseInt(q.get("pageNum")):1,size=q.containsKey("pageSize")?Integer.parseInt(q.get("pageSize")):20;require(page>0&&page<=100000&&size>0&&size<=100,"每页最多100行");String where=" WHERE company_code=? AND parent_id=?";List<Object>a=new ArrayList<>(Arrays.asList(c,id));if(!sku.isEmpty()){where+=" AND sku_sn=?";a.add(sku);}if(status.equals("ABNORMAL"))where+=" AND status<>'MATCHED'";else if(!status.isEmpty()){where+=" AND status=?";a.add(status);}long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation_result"+where,Long.class,a.toArray());a.add(size);a.add((page-1)*size);List<Map<String,Object>>rows=new ArrayList<>();for(Map<String,Object>r:db.jdbc.queryForList("SELECT id,row_json FROM warehouse_reconciliation_result"+where+" ORDER BY sort_order,id LIMIT ? OFFSET ?",a.toArray())){Map<String,Object>x=scope.obj(r.get("row_json"));x.put("result_id",r.get("id"));rows.add(x);}return map("rows",rows,"total",total);}
 /** Stream bounded keyset pages; capture a high watermark so concurrent projections cannot make export endless. */
 public void export(String c,long id,Map<String,String>q,java.io.Writer writer)throws java.io.IOException{get(c,id);String status=text(q.get("status")),sku=text(q.get("sku_sn"));require(status.matches("[A-Z_]{0,40}")&&sku.length()<=128,"导出筛选无效");String where=" WHERE company_code=? AND parent_id=?";List<Object>a=new ArrayList<>(Arrays.asList(c,id));if(!sku.isEmpty()){where+=" AND sku_sn=?";a.add(sku);}if(status.equals("ABNORMAL"))where+=" AND status<>'MATCHED'";else if(!status.isEmpty()){where+=" AND status=?";a.add(status);}Map<String,Object>count=db.one("SELECT COUNT(*) total,COALESCE(MAX(id),0) maximum FROM warehouse_reconciliation_result"+where,a.toArray());require(n(count,"total")<=100000,"导出最多100000行，请筛选结论或SKU后重试");writer.write("SKU,批次,质量,OMS实物,WMS实物,实物差额,OMS业务占用,WMS冻结,结论,失败说明\r\n");long cursor=0,maximum=n(count,"maximum");while(cursor<maximum){List<Object>args=new ArrayList<>(a);args.add(cursor);args.add(maximum);List<Map<String,Object>>page=db.jdbc.queryForList("SELECT id,row_json FROM warehouse_reconciliation_result"+where+" AND id>? AND id<=? ORDER BY id LIMIT 200",args.toArray());if(page.isEmpty())break;for(Map<String,Object>row:page){Map<String,Object>r=scope.obj(row.get("row_json"));List<String>cells=new ArrayList<>();for(String k:Arrays.asList("sku_sn","batch_code","inventory_type","oms_physical","wms_physical","difference","oms_held","wms_frozen","status","error")){String value=r.get(k)==null?"未知":text(r.get(k));if(Arrays.asList("sku_sn","batch_code","error").contains(k)||value.matches("^[=+@\\t\\r].*"))value="'"+value;cells.add("\""+value.replace("\"","\"\"")+"\"");}writer.write(String.join(",",cells)+"\r\n");cursor=n(row,"id");}writer.flush();}writer.flush();}
 public long recheck(String c,long id,Map<String,Object>cmd,String actor){Map<String,Object>d=get(c,id);List<String>skus=scope.skus(cmd.get("skus"));for(String sku:skus)require(db.jdbc.queryForObject("SELECT COUNT(*) FROM warehouse_reconciliation WHERE company_code=? AND parent_id=? AND item_sku=?",Long.class,c,id,sku)==1,"复查SKU不属于本任务");Map<String,Object>body=map("request_key",required(cmd,"request_key",64),"store_code",d.get("store_code"),"skus",skus,"method",skus.size()==1?"stock.query":"inventory.query","source_check_id",id);return reconciliation.create(c,body,actor);}
}
